def obc(c):
 o=c['obc']; vsmin=o['source_voltage_v'][0]-o['dynamic_deviation_v']; vmax=o['source_voltage_v'][1]+o['dynamic_deviation_v']; disc=vsmin**2-4*o['loop_resistance_max_ohm']*o['power_max_w']; vmin=(vsmin+sqrt(disc))/2 if disc>=0 else 0
 rw=2*o['effective_conductor_length_max_m']*o['wire_r20_ohm_per_m_screen']*(1+o['copper_alpha_per_C']*(o['wire_max_temp_C']-20))
 return {'source_dynamic_min_v':vsmin,'load_worst_min_v':vmin,'load_worst_max_at_zero_current_v':vmax,'margin_low_v':vmin-o['load_range_v'][0],'margin_high_v':o['load_range_v'][1]-vmax,'max_current_a':o['power_max_w']/vmin if vmin else None,'wire_screen_ohm':rw,'wire_plus_contact_screen_ohm':rw+o['other_loop_resistance_budget_ohm'],'required_source_min_before_dynamic_v':o['load_range_v'][0]+o['power_max_w']*o['loop_resistance_max_ohm']/o['load_range_v'][0]+o['dynamic_deviation_v'],'required_source_max_before_dynamic_v':o['load_range_v'][1]-o['dynamic_deviation_v'],'conditional_voltage_pass':vmin>=o['load_range_v'][0] and vmax<=o['load_range_v'][1] and not(o['p1_powered'] and o['fsi_powered']),'source_guarantee_not_established':True}
def pv(c):
 v=c['pv']; e=c['eps']; cold=(v['cell_voc_BOL_28C']+v['dvoc_BOL_per_C']*(v['cold_C']-28))*v['voc_tolerance_factor_requirement']; hot=(v['cell_vmp_EOL_1e15_28C']+v['dvmp_EOL_per_C']*(v['hot_C']-28))*v['vmp_tolerance_factor_requirement']; ihot=(v['cell_isc_BOL_28C']+v['disc_BOL_per_C']*(v['hot_C']-28))*v['irradiance_current_factor_requirement']; voc=v['Ns']*cold; vmpp=v['Ns']*hot-v['string_blocking_drop_max_v_requirement']-v['harness_drop_max_v_requirement']; cap=min(v['acu_input_range_v'][1],e['battery_operating_v'][0]-v['boost_headroom_requirement_v']); isc=ihot*v['Np']; imp=(v['cell_imp_EOL_1e15_28C']+v['dimp_EOL_per_C']*(v['hot_C']-28))*v['Np']; total=v['channels']*v['Ns']*v['Np']; sunw=vmpp*imp*v['channels']*v['incidence_factor_assumption']*v['assembly_degradation_factor_assumption']*e['acu_efficiency_requirement']
 return {'cold_voc_screen_v':voc,'cold_voc_required_max_v':cap,'hot_EOLe15_mpp_at_ACU_v':vmpp,'channel_max_isc_screen_a':isc,'series_bounds_screen':[ceil((v['acu_input_range_v'][0]+v['string_blocking_drop_max_v_requirement']+v['harness_drop_max_v_requirement'])/hot),int(cap/cold)],'parallel_max_screen':int(v['acu_input_current_a']/ihot),'installed_cells':total,'cell_glass_footprint_m2':total*v['cell_glass_rectangle_m'][0]*v['cell_glass_rectangle_m'][1],'panel_area_requirement_m2':total*v['cell_glass_rectangle_m'][0]*v['cell_glass_rectangle_m'][1]/v['packing_factor_assumption'],'CIC_mass_only_reference_kg':total*v['cell_mass_reference_kg'],'sun_bus_power_conditional_w':sunw,'conditional_range_pass':voc<cap and vmpp>=v['acu_input_range_v'][0] and isc<=v['acu_input_current_a'],'cold_extrapolation_outside_datasheet_coefficient_range':v['cold_C']<28,'actual_array_range_pass':None,'guaranteed_cold_Voc_upper_bound_required':cap/v['Ns']}
def modes(c,pr):
 e=c['eps']; rows=[]
 for m in c['modes']:
  load=m['OBC_w']+m['other_loads_w']+m['propulsion_w']; batt=load/e['pdu_efficiency_requirement']+e['standby_allocation_w']+m['heater_w']; rows.append({**m,'regulated_load_w':load,'battery_equivalent_w':batt,'energy_wh':batt*m['duration_min']/60})
 eclipse=sum(x['energy_wh'] for x in rows if not x['sun']); sun=sum(x['energy_wh'] for x in rows if x['sun']); sun_h=sum(x['duration_min'] for x in rows if x['sun'])/60; req=sun/sun_h+eclipse/e['charge_efficiency_requirement']/sun_h; usable=e['capacity_reference_wh']*e['capacity_window_factor_requirement']*e['capacity_temperature_factor_requirement']*e['capacity_age_factor_requirement']*e['operational_DOD_requirement']; peak=(c['peak']['PDU_total_w']/e['pdu_efficiency_requirement']+e['standby_allocation_w']+c['peak']['direct_heater_w'])/e['battery_operating_v'][0]; pdui=c['peak']['PDU_total_w']/e['pdu_efficiency_requirement']/e['battery_operating_v'][0]
 return {'mode_rows':rows,'orbital_window_identity':'95 min illustrative requirement window; not propagated mission orbit','total_energy_wh':sum(x['energy_wh'] for x in rows),'eclipse_energy_wh':eclipse,'sun_bus_power_required_w':req,'sun_bus_power_margin_w':pr['sun_bus_power_conditional_w']-req,'eclipse_capacity_allocated_wh':usable,'eclipse_energy_pass_conditional':usable>=eclipse,'battery_peak_a':peak,'pdu_input_peak_a':pdui,'peak_limits_pass':peak<=e['dock_total_current_a'] and pdui<=e['pdu_input_current_a'],'minimum_incidence_factor_for_energy':c['pv']['incidence_factor_assumption']*req/pr['sun_bus_power_conditional_w'],'future_arm_360W_battery_current_a':(360/e['pdu_efficiency_requirement']+e['standby_allocation_w'])/e['battery_operating_v'][0],'actual_mission_complete':False}
def regen(c):
 s=c['stop']; vlo=s['bus_nominal_v']*(1-s['bus_tolerance_fraction'])+s['deactivation_offset_min_v']; vhi=s['bus_nominal_v']*(1+s['bus_tolerance_fraction'])+s['activation_offset_max_v']; rlo=s['RB1_resistance_ohm']*(1-s['RB1_tolerance_requirement']); rhi=s['RB1_resistance_ohm']*(1+s['RB1_tolerance_requirement']); pmin=vlo**2/rhi; pmax=vhi**2/rlo; imax=vhi/rlo; req=s['stop_energy_requirement_j']/s['stop_window_requirement_s']; avg=s['stop_energy_requirement_j']/s['repeat_period_requirement_s']; return {'resistor_on_power_interval_w':[pmin,pmax],'brake_peak_a':imax,'required_absorb_power_w':req,'repeat_average_w':avg,'electrical_arithmetic_pass':req<=pmin and imax<=s['brake_current_free_air_25C_a'] and avg<=s['RB1_derated_average_limit_w_requirement'],'contactor_low_current_loss_at15A_requirement_w':15**2*s['K1_low_current_acceptance_ohm_requirement'],'U1_input_loss_absorption_verified':s['U1_input_loss_absorption_verified'],'motion_permit':False,'pulse_curve_and_DM_bus_absmax_not_bound':True}
def validate(c):
 err=[]; ob=obc(c); pr=pv(c); mo=modes(c,pr); re=regen(c)
 if not ob['conditional_voltage_pass']:err.append('OBC_VOLTAGE_OR_DUAL_SUPPLY')
 if not pr['conditional_range_pass']:err.append('PV_RANGE_OR_CURRENT')
 if not c['pv']['per_string_blocking_diode']:err.append('STRING_REVERSE_CURRENT_PATH')
 if c['configuration']['parallel_RSP_BPX']:err.append('UNAUTHORIZED_SOURCE_PARALLEL')
 if c['eps']['bpx_pin14_connected']:err.append('BPX_PIN14_NC_CONFLICT')
 if c['eps']['charge_limit_requirement_a']>min(c['eps']['bpx_charge_max_a'],c['eps']['dock_total_current_a']):err.append('CHARGE_CURRENT_EXCESS')
 if c['eps']['charge_cv_requirement_v']+c['eps']['charge_voltage_tolerance_v']>c['eps']['battery_operating_v'][1]:err.append('CHARGE_CV_EXCESS')
 if c['eps']['charge_temperature_requirement_C'][0]<0 or c['eps']['charge_temperature_requirement_C'][1]>45:err.append('CHARGE_TEMPERATURE_EXCESS')
 if mo['sun_bus_power_margin_w']<0:err.append('ENERGY_RECHARGE_DEFICIT')
 if not mo['eclipse_energy_pass_conditional']:err.append('ECLIPSE_CAPACITY_DEFICIT')
 if not mo['peak_limits_pass']:err.append('DOCK_OR_PDU_PEAK_EXCESS')
 if c['peak']['propulsion_12V_branch_peak_w']/12>c['peak']['single_PDU_channel_a']:err.append('PROPULSION_CHANNEL_EXCESS')
 if c['peak'].get('regulator2_5V_peak_w',18)/5>c['peak']['regulator_combined_a']:err.append('REGULATOR_SHARED_EXCESS')
 if not re['electrical_arithmetic_pass']:err.append('REGEN_POWER_CURRENT_OR_REPEAT_EXCESS')
 if c['stop']['motion_permit'] and not c['stop']['U1_input_loss_absorption_verified']:err.append('STOP_DROPOUT_UNVERIFIED')
 if c['build_approved']:err.append('UNSATISFIED_PHYSICAL_RELEASE')
 return err
def main():
 ip=P/'POWER_CONTRACT.json'
 if not ip.exists():dump(ip,DEFAULT)
 c=json.loads(ip.read_text(encoding='utf-8')); p=pv(c); result={'status':'CONDITIONAL_DESIGN_CALCULATED__NOT_HARDWARE_RELEASE','obc':obc(c),'pv':p,'budget':modes(c,p),'regen':regen(c),'nominal_validation_errors':validate(c),'physical_tests':0,'build_approved':False}
 cases=[('OBC_long_hot_harness',['obc','loop_resistance_max_ohm'],0.30,'OBC_VOLTAGE_OR_DUAL_SUPPLY'),('OBC_excess_upper_setpoint',['obc','source_voltage_v'],[3.28,3.39],'OBC_VOLTAGE_OR_DUAL_SUPPLY'),('P1_FSI_double_feed',['obc','fsi_powered'],True,'OBC_VOLTAGE_OR_DUAL_SUPPLY'),('PV_8_series_cold',['pv','Ns'],8,'PV_RANGE_OR_CURRENT'),('PV_4_parallel',['pv','Np'],4,'PV_RANGE_OR_CURRENT'),('PV_shadow',['pv','incidence_factor_assumption'],0.2,'ENERGY_RECHARGE_DEFICIT'),('PV_missing_blocking',['pv','per_string_blocking_diode'],False,'STRING_REVERSE_CURRENT_PATH'),('BPX_NC_pin14_connected',['eps','bpx_pin14_connected'],True,'BPX_PIN14_NC_CONFLICT'),('battery_charge_cold',['eps','charge_temperature_requirement_C'],[-1,40],'CHARGE_TEMPERATURE_EXCESS'),('battery_charge4A',['eps','charge_limit_requirement_a'],4,'CHARGE_CURRENT_EXCESS'),('arm360W_on_PDU',['peak','PDU_total_w'],360,'DOCK_OR_PDU_PEAK_EXCESS'),('RSP_BPX_parallel',['configuration','parallel_RSP_BPX'],True,'UNAUTHORIZED_SOURCE_PARALLEL'),('regen200J_250ms',['stop','stop_energy_requirement_j'],200,'REGEN_POWER_CURRENT_OR_REPEAT_EXCESS'),('regen_repeated_1Hz',['stop','repeat_period_requirement_s'],1,'REGEN_POWER_CURRENT_OR_REPEAT_EXCESS'),('dropout_claims_motion',['stop','motion_permit'],True,'STOP_DROPOUT_UNVERIFIED'),('premature_release',['build_approved'],True,'UNSATISFIED_PHYSICAL_RELEASE')]
 negatives=[]
 cases += [('overcharge_CV',['eps','charge_cv_requirement_v'],32.1,'CHARGE_CV_EXCESS'),('propulsion25W',['peak','propulsion_12V_branch_peak_w'],25,'PROPULSION_CHANNEL_EXCESS'),('5V_shared25W',['peak','regulator2_5V_peak_w'],25,'REGULATOR_SHARED_EXCESS')]
 for name,path,value,expected in cases:
  bad=copy.deepcopy(c); node=bad
  for k in path[:-1]:node=node[k]
  node[path[-1]]=value; errors=validate(bad); negatives.append({'case':name,'input_mutation':{'.'.join(path):value},'expected':expected,'observed':errors,'detected':expected in errors})
 result['negative_controls']=negatives; result['all_negative_controls_detected']=all(x['detected'] for x in negatives)
 result['source_hashes']={p.name:sha(p) for p in S.iterdir() if p.is_file()}; result['contract_sha256']=sha(ip);result['calculator_sha256']=sha(Path(__file__))
 dump(R/'POWER_CALCULATIONS.json',result)
 print(json.dumps({k:result[k] for k in ['status','obc','pv','budget','regen','nominal_validation_errors','all_negative_controls_detected']},ensure_ascii=False,indent=2))
 if result['nominal_validation_errors'] or not result['all_negative_controls_detected']:raise SystemExit(1)
if __name__=='__main__':main()
